{$ param sidebar_width label="Sidebar Width (px)" default="250" description="Width of the sidebar column in pixels at large breakpoint." $}

<div class="flex flex-col lg:flex-row mt-8 backport">
  <div class="order-2 lg:order-1 mb-8 lg:pr-8 lg:border-r lg:mr-8 border-light-gray" style="flex: 0 0 {$= sidebar_width $}px; max-width: {$= sidebar_width $}px;">
    <div class="lg:sticky top-0">
      {$ slot sidebar $}
        <p class="ss-xsmall">Sidebar content.</p>
      {$ /slot $}
    </div>
  </div>
  <div class="order-1 lg:order-2 mb-8 max-w-full w-[1100px] mx-auto flex-1">
    {$ slot main $}
      <p class="ss-text">Main content.</p>
    {$ /slot $}
  </div>
</div>
